import 'dart:io';import 'package:flutter/foundation.dart';import 'package:flutter/material.dart';import '../data/app_database.dart';import '../data/product.dart';import '../services/csv_service.dart';
class DatasetPage extends StatefulWidget{const DatasetPage({super.key,required this.datasetId,required this.datasetName,required this.onAdd});final String datasetId,datasetName;final VoidCallback onAdd;@override State<DatasetPage> createState()=>_DatasetPageState();}
class _DatasetPageState extends State<DatasetPage>{final search=TextEditingController();List<Product> items=[];int total=0,photos=0;@override void initState(){super.initState();load();}@override void didUpdateWidget(covariant DatasetPage old){super.didUpdateWidget(old);if(old.datasetId!=widget.datasetId)load();}@override void dispose(){search.dispose();super.dispose();}Future<void> load() async{final a=await AppDatabase.instance.products(widget.datasetId,query:search.text);final c=await AppDatabase.instance.productCount(widget.datasetId);final ph=await AppDatabase.instance.photoCount(widget.datasetId);if(mounted)setState(()=>{items=a,total=c,photos=ph});}Future<void> imp() async{final m=await CsvService.importCsv(widget.datasetId);if(mounted){await load();ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(m)));}}Future<void> exp() async{try{await CsvService.shareCsv(widget.datasetId,widget.datasetName);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('فشل التصدير: $e')));}}
 Widget stat(String t,int n,IconData i)=>Expanded(child:Card(child:Padding(padding:const EdgeInsets.all(10),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(i,color:const Color(0xFF0B7A55)),Text('$n',style:const TextStyle(fontSize:22,fontWeight:FontWeight.w700)),Text(t,style:const TextStyle(fontSize:11))]))));
 @override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.all(14),child:Column(children:[Row(children:[stat('المنتجات',total,Icons.inventory_2_outlined),stat('لها صور',photos,Icons.photo_outlined),stat('محلية',total,Icons.offline_pin_outlined)]),const SizedBox(height:8),TextField(controller:search,onChanged:(_)=>load(),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'بحث بالاسم أو الباركود')),const SizedBox(height:8),Expanded(child:items.isEmpty?Center(child:Text('لا توجد منتجات بعد')):ListView.builder(itemCount:items.length,itemBuilder:(ctx,i){final x=items[i];final im=x.frontImage.isNotEmpty?x.frontImage:x.backImage;return Card(child:ListTile(leading:Container(width:52,height:52,decoration:BoxDecoration(color:const Color(0xFFE3E8EE),borderRadius:BorderRadius.circular(10)),child:im.isNotEmpty&&!kIsWeb?Image.file(File(im),fit:BoxFit.cover,errorBuilder:(_,__,___)=>const Icon(Icons.image_not_supported)):const Icon(Icons.inventory_2_outlined)),title:Text(x.name),subtitle:Text(x.barcode.isEmpty?'بدون باركود':x.barcode)));})),Row(children:[Expanded(child:OutlinedButton.icon(onPressed:imp,icon:const Icon(Icons.file_upload_outlined),label:const Text('استيراد CSV'))),const SizedBox(width:8),Expanded(child:FilledButton.icon(onPressed:exp,icon:const Icon(Icons.share_outlined),label:const Text('CSV ومشاركة')))])]));}
